<?php
namespace Delnavazan\Platform\Core\Infrastructure\Repository;
final class OperationalExceptionRepository extends BaseRepository { public function __construct(){global $wpdb;$this->table=$wpdb->prefix.'dzn_operational_exceptions';} public function activeFingerprint(string $fingerprint):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table} WHERE fingerprint=%s AND status IN ('open','acknowledged') ORDER BY id DESC LIMIT 1",$fingerprint));} public function seen(int $id,string $now):void{global $wpdb;if(false===$wpdb->update($this->table,['last_seen_at'=>$now],['id'=>$id]))throw new \RuntimeException($wpdb->last_error);} public function transition(int $id,string $status,string $now,?int $actor,?string $note):void{global $wpdb;$data=['status'=>$status];if($status!=='acknowledged')$data+=['resolved_at'=>$now,'resolved_by'=>$actor,'resolution_note'=>$note];$result=$wpdb->query($wpdb->prepare("UPDATE {$this->table} SET status=%s,resolved_at=%s,resolved_by=%d,resolution_note=%s WHERE id=%d AND status IN ('open','acknowledged')",$status,$data['resolved_at']??null,$data['resolved_by']??0,$data['resolution_note']??null,$id));if(false===$result||$result!==1)throw new \RuntimeException('Invalid exception transition');} public function incrementRetry(int $id):void{global $wpdb;if(false===$wpdb->query($wpdb->prepare("UPDATE {$this->table} SET retry_count=retry_count+1 WHERE id=%d",$id)))throw new \RuntimeException($wpdb->last_error);} }
